for n in ['043_ee','044_ee']:
 p='/app/output/records/'+n+'/robot_r1_left_realsense_link_Camera_0.jpg'; im=Image.open(p).resize((672,672)); d=ImageDraw.Draw(im)
 for v in range(0,225,20):
  y=v*3; d.line((0,y,672,y),fill=(255,0,0),width=1);d.text((0,y),str(v),fill=(255,0,0))
 for u in range(0,225,20):
  x=u*3;d.line((x,0,x,672),fill=(255,0,0),width=1);d.text((x,0),str(u),fill=(255,0,0))
 im.save('/app/output/'+n+'_grid.png')
PY

